export const ALL_PRODUCTS: Product[] = P;
export function getProductBySlug(slug: string) { return P.find(p => p.slug === slug); }
export function getProductsByCategory(slug: string) { return P.filter(p => p.categorySlug === slug); }
export function getCategoryBySlug(slug: string) { return CATEGORIES.find(c => c.slug === slug); }

